    {
        if (isHeadChef)
        {
            Console.WriteLine("Head Chef is managing kitchen staff.");
        }
        else
        {
            Console.WriteLine("Chef does not manage staff.");
        }
    }

    public void HandlePayments()
    {
        Console.WriteLine("Chef does not handle payments.");
    }

    public void OrderSupplies()
    {
        if (isHeadChef)
        {
            for (int i = 1; i <= 3; i++)
