    {
        foreach (string dishType in dishTypes)
        {
            if (dirtyItems > 0)
            {
                if (dishType.Equals("pots") && isIndustrialGrade)
                {
                    for (int cycle = 1; cycle <= 3; cycle++)
                    {
                        Console.WriteLine("Industrial dishwasher cleaning " + dishType + " cycle " + cycle);
                        dirtyItems -= 2;
