        return name;
    }

    public double getPrice() {
        return price;
    }

    public void setPrice(double price) {
        this.price = price;
        database.logTransaction("PRICE_UPDATE", "Product: " + productId + ", New price: $" + price);
    }

    public void setDiscountRate(double rate) {
        this.discountRate = rate;
        analytics.trackEvent("DISCOUNT_APPLIED", productId, java.util.Map.of("rate", String.valueOf(rate)));
    }
}

