class Product(val name: String, var price: Double) {
    var productId: String = ""
        private set
    var category: String = ""
        private set
    var stockQuantity: Int = 100
    var weight: Double = 1.0
        private set
    var description: String = ""
        private set
    val customerReviews: MutableList<String> = mutableListOf()
    var averageRating: Double = 0.0
    var totalSales: Int = 0
    var costPrice: Double = price * 0.6
        private set
    val customerEmails: MutableList<String> = mutableListOf()
    var isActive: Boolean = true
        private set
    var supplier: String = ""
        private set
    var discountRate: Double = 0.0
    val salesByRegion: MutableMap<String, Int> = mutableMapOf()

    private val database = InventoryDatabase("jdbc:mysql://localhost:3306/inventory")
    private val emailService = EmailService("smtp.ecommerce.com")
    private val paymentProcessor = PaymentProcessor("pay_api_key_123")
    private val shippingService = ShippingService("FedEx")
    private val analytics = AnalyticsService("analytics_key_456")

    init {
        initializeAdvancedDefaults()
    }

    fun applyDiscount(percentage: Double): Double {
        return price * (1 - percentage / 100)
    }

    fun displayProduct() {
        println("Product: $name, Price: $$price")
    }

    fun generateAdvancedProductId(): String {
        val categoryPrefix = if (category.isNotEmpty()) {
            category.substring(0, minOf(3, category.length)).uppercase()
        } else "GEN"
        val timestamp = (System.currentTimeMillis() % 100000).toString()
        val checksum = (Math.abs(name.hashCode() % 100)).toString()
        return "$categoryPrefix-$timestamp-$checksum"
    }

    fun calculateDynamicPricing(): Double {
        val demandMultiplier = when {
            totalSales > 1000 -> 1.2
            totalSales > 500 -> 1.1
            else -> 1.0
        }
        val stockMultiplier = if (stockQuantity < 10) 1.15 else 1.0
        val seasonalMultiplier = if (java.time.LocalDate.now().monthValue == 12) 1.25 else 1.0
        return price * demandMultiplier * stockMultiplier * seasonalMultiplier * (1 - discountRate)
    }

    fun calculateComplexProfitMargin(): Double {
        val sellingPrice = calculateDynamicPricing()
        val shippingCost = shippingService.calculateShippingRate("domestic", weight)
        val totalCost = costPrice + shippingCost + (sellingPrice * 0.03)
        return ((sellingPrice - totalCost) / sellingPrice) * 100
    }

    fun calculateTieredDiscount(quantity: Int): Double {
        return when {
            quantity >= 100 -> 0.20
            quantity >= 50 -> 0.15
            quantity >= 10 -> 0.10
            quantity >= 5 -> 0.05
            else -> 0.0
        }
    }

    fun validateProductCompliance(): Boolean {
        val hasValidName = name.length in 3..100
        val hasValidPrice = price > 0 && price <= 10000
        val hasValidWeight = weight > 0 && weight <= 50
        val hasValidStock = stockQuantity >= 0
        return hasValidName && hasValidPrice && hasValidWeight && hasValidStock
    }

    fun processAdvancedReview(customerEmail: String, review: String, rating: Double, region: String) {
        if (rating in 1.0..5.0 && review.length >= 10) {
            customerReviews.add(review)
            customerEmails.add(customerEmail)
            recalculateAdvancedRating(rating)

            val thankYouEmail = createReviewThankYouEmail(customerEmail, rating)
            emailService.sendEmail(customerEmail, "Thank you for your review!", thankYouEmail)

            val analyticsData = mapOf(
                "rating" to rating.toString(),
                "region" to region
            )
            analytics.trackEvent("REVIEW_ADDED", productId, analyticsData)

            database.logTransaction("REVIEW_PROCESSED", "Product: $productId, Rating: $rating, Region: $region")
        }
    }

    fun recalculateAdvancedRating(newRating: Double) {
        averageRating = if (customerReviews.size == 1) {
            newRating
        } else {
            val weightedTotal = averageRating * (customerReviews.size - 1) + newRating
            weightedTotal / customerReviews.size
        }

        if (averageRating >= 4.5 && customerReviews.size >= 10) {
            triggerBestSellerPromotion()
        }
    }

    fun createReviewThankYouEmail(customerEmail: String, rating: Double): String {
        return buildString {
            append("Dear Valued Customer,\n\n")
            append("Thank you for your $rating-star review of $name!\n")
            append("Your feedback helps other customers make informed decisions.\n\n")
            if (rating >= 4.0) {
                append("As a token of appreciation, here's a 10% discount code: REVIEW10\n\n")
            }
            append("Best regards,\nCustomer Service Team")
        }
    }

    fun triggerBestSellerPromotion() {
        val promoEmail = "BESTSELLER ALERT: $name is now a top-rated product with $averageRating stars!"
        emailService.sendBulkEmail(customerEmails, "Special Offer on Bestseller", promoEmail)
        analytics.trackEvent("BESTSELLER_PROMOTION", productId, emptyMap())
    }

    fun processComplexSale(
        quantity: Int,
        customerEmail: String,
        shippingAddress: String,
        region: String,
        cardNumber: String
    ): String {
        if (stockQuantity < quantity) {
            return "FAILED: Insufficient stock"
        }

        val unitPrice = calculateDynamicPricing()
        val discount = calculateTieredDiscount(quantity)
        val subtotal = unitPrice * quantity * (1 - discount)
        val shippingCost = shippingService.calculateShippingRate(region, weight * quantity)
        val totalAmount = subtotal + shippingCost

        if (!paymentProcessor.processPayment(totalAmount, cardNumber)) {
            return "FAILED: Payment declined"
        }

        stockQuantity -= quantity
        totalSales += quantity
        salesByRegion[region] = salesByRegion.getOrDefault(region, 0) + quantity

        val trackingNumber = shippingService.createShipment(shippingAddress, weight * quantity)

        database.updateStock(productId, stockQuantity)

        val receiptEmail = generateAdvancedReceipt(quantity, unitPrice, discount, shippingCost, totalAmount, trackingNumber)
        emailService.sendEmail(customerEmail, "Order Confirmation - $name", receiptEmail)

        checkAdvancedStockAlerts()

        val saleData = mapOf(
            "quantity" to quantity.toString(),
            "amount" to totalAmount.toString(),
            "region" to region
        )
        analytics.trackEvent("SALE_COMPLETED", productId, saleData)

        database.logTransaction("COMPLEX_SALE", "Product: $productId, Qty: $quantity, Amount: $$totalAmount, Region: $region")

        return "SUCCESS: Order placed - Tracking: $trackingNumber"
    }

    fun generateAdvancedReceipt(
        quantity: Int,
        unitPrice: Double,
        discount: Double,
        shipping: Double,
        total: Double,
        tracking: String
    ): String {
        return "ORDER RECEIPT\n" +
               "Product: $name ($productId)\n" +
               "Quantity: $quantity\n" +
               "Unit Price: $${String.format("%.2f", unitPrice)}\n" +
               "Discount: ${String.format("%.0f", discount * 100)}%\n" +
               "Shipping: $${String.format("%.2f", shipping)}\n" +
               "Total: $${String.format("%.2f", total)}\n" +
               "Tracking: $tracking\n" +
               "Thank you for your order!"
    }

    fun checkAdvancedStockAlerts() {
        when {
            stockQuantity <= 5 -> {
                val urgentAlert = "URGENT: Product $name ($productId) critically low - Only $stockQuantity units left!"
                emailService.sendEmail("urgent@company.com", "Critical Stock Alert", urgentAlert)
                analytics.trackEvent("CRITICAL_STOCK_ALERT", productId, emptyMap())
            }
            stockQuantity <= 20 -> {
                val alert = "LOW STOCK: Product $name has $stockQuantity units remaining."
                emailService.sendEmail("inventory@company.com", "Low Stock Alert", alert)
            }
        }
    }

    fun executeSmartRestock(supplierEmail: String) {
        val recommendedStock = calculateOptimalStockLevel()
        val restockQuantity = recommendedStock - stockQuantity

        if (restockQuantity > 0) {
            stockQuantity += restockQuantity
            database.updateStock(productId, stockQuantity)

            val restockEmail = generateSmartRestockEmail(restockQuantity, recommendedStock)
            emailService.sendEmail(supplierEmail, "Smart Restock Completed - $name", restockEmail)

            analytics.trackEvent("SMART_RESTOCK", productId, mapOf("quantity" to restockQuantity.toString()))
            database.logTransaction("SMART_RESTOCK", "Product: $productId, Added: $restockQuantity, Target: $recommendedStock")
        }
    }

    fun calculateOptimalStockLevel(): Int {
        val averageMonthlySales = totalSales / maxOf(1, java.time.LocalDate.now().monthValue)
        val seasonalFactor = if (java.time.LocalDate.now().monthValue == 12) 2 else 1
        return averageMonthlySales * 2 * seasonalFactor
    }

    fun generateSmartRestockEmail(quantity: Int, targetLevel: Int): String {
        return "SMART RESTOCK REPORT\n" +
               "Product: $name ($productId)\n" +
               "Restocked Quantity: $quantity\n" +
               "New Stock Level: $stockQuantity\n" +
               "Target Level: $targetLevel\n" +
               "Sales Velocity: ${totalSales / maxOf(1, java.time.LocalDate.now().dayOfYear)} units/day\n" +
               "Restock completed successfully."
    }

    fun generateComprehensiveAnalytics(): String {
        val totalRevenue = totalSales * calculateDynamicPricing()
        val profitMargin = calculateComplexProfitMargin()
        val topRegion = salesByRegion.maxByOrNull { it.value }?.key ?: "N/A"

        return "COMPREHENSIVE ANALYTICS\n" +
               "Product: $name ($productId)\n" +
               "Total Sales: $totalSales units\n" +
               "Revenue: $${String.format("%.2f", totalRevenue)}\n" +
               "Profit Margin: ${String.format("%.2f", profitMargin)}%\n" +
               "Average Rating: ${String.format("%.2f", averageRating)} (${customerReviews.size} reviews)\n" +
               "Top Region: $topRegion\n" +
               "Stock Level: $stockQuantity\n" +
               "Current Price: $${String.format("%.2f", calculateDynamicPricing())}"
    }

    fun launchMarketingCampaign(campaignType: String) {
        val campaignEmail = createCampaignEmail(campaignType)
        emailService.sendBulkEmail(customerEmails, "Special Campaign - $name", campaignEmail)

        val campaignData = mapOf(
            "type" to campaignType,
            "reach" to customerEmails.size.toString()
        )
        analytics.trackEvent("MARKETING_CAMPAIGN", productId, campaignData)

        database.logTransaction("CAMPAIGN_LAUNCHED", "Product: $productId, Type: $campaignType, Reach: ${customerEmails.size}")
    }

    fun createCampaignEmail(campaignType: String): String {
        return when (campaignType) {
            "SEASONAL" -> "Don't miss our seasonal special on $name! Limited time offer with up to 25% off!"
            "CLEARANCE" -> "CLEARANCE ALERT: $name must go! Huge discounts available now!"
            else -> "Special promotion on $name - Check out our latest deals!"
        }
