class Product:
    def __init__(self, name, price):
        self.name = name
        self.price = price
        self.product_id = self.generate_advanced_product_id()
        self.category = None
        self.stock_quantity = 100
        self.weight = 1.0
        self.description = None
        self.customer_reviews = []
        self.average_rating = 0.0
        self.total_sales = 0
        self.cost_price = price * 0.6
        self.customer_emails = []
        self.is_active = True
        self.supplier = None
        self.discount_rate = 0.0
        self.sales_by_region = {}

        self.database = InventoryDatabase("jdbc:mysql://localhost:3306/inventory")
        self.email_service = EmailService("smtp.ecommerce.com")
        self.payment_processor = PaymentProcessor("pay_api_key_123")
        self.shipping_service = ShippingService("FedEx")
        self.analytics = AnalyticsService("analytics_key_456")

        self.initialize_advanced_defaults()

    def apply_discount(self, percentage):
        return self.price * (1 - percentage / 100)

    def display_product(self):
        print(f"Product: {self.name}, Price: ${self.price}")

    def generate_advanced_product_id(self):
        category_prefix = self.category[:min(3, len(self.category))].upper() if self.category else "GEN"
        import time
        timestamp = str(int(time.time() * 1000) % 100000)
        checksum = str(abs(hash(self.name) % 100))
        return f"{category_prefix}-{timestamp}-{checksum}"

    def calculate_dynamic_pricing(self):
        demand_multiplier = 1.2 if self.total_sales > 1000 else (1.1 if self.total_sales > 500 else 1.0)
        stock_multiplier = 1.15 if self.stock_quantity < 10 else 1.0

        import datetime
        seasonal_multiplier = 1.25 if datetime.datetime.now().month == 12 else 1.0

        return self.price * demand_multiplier * stock_multiplier * seasonal_multiplier * (1 - self.discount_rate)

    def calculate_complex_profit_margin(self):
        selling_price = self.calculate_dynamic_pricing()
        shipping_cost = self.shipping_service.calculate_shipping_rate("domestic", self.weight)
        total_cost = self.cost_price + shipping_cost + (selling_price * 0.03)
        return ((selling_price - total_cost) / selling_price) * 100

    def calculate_tiered_discount(self, quantity):
        if quantity >= 100:
            return 0.20
        elif quantity >= 50:
            return 0.15
        elif quantity >= 10:
            return 0.10
        elif quantity >= 5:
            return 0.05
        return 0.0

    def validate_product_compliance(self):
        has_valid_name = self.name is not None and 3 <= len(self.name) <= 100
        has_valid_price = 0 < self.price <= 10000
        has_valid_weight = 0 < self.weight <= 50
        has_valid_stock = self.stock_quantity >= 0
        return has_valid_name and has_valid_price and has_valid_weight and has_valid_stock

    def process_advanced_review(self, customer_email, review, rating, region):
        if 1.0 <= rating <= 5.0 and len(review) >= 10:
            self.customer_reviews.append(review)
            self.customer_emails.append(customer_email)
            self.recalculate_advanced_rating(rating)

            thank_you_email = self.create_review_thank_you_email(customer_email, rating)
            self.email_service.send_email(customer_email, "Thank you for your review!", thank_you_email)

            analytics_data = {
                "rating": str(rating),
                "region": region
            }
            self.analytics.track_event("REVIEW_ADDED", self.product_id, analytics_data)

            self.database.log_transaction("REVIEW_PROCESSED", f"Product: {self.product_id}, Rating: {rating}, Region: {region}")

    def recalculate_advanced_rating(self, new_rating):
        if len(self.customer_reviews) == 1:
            self.average_rating = new_rating
        else:
            weighted_total = self.average_rating * (len(self.customer_reviews) - 1) + new_rating
            self.average_rating = weighted_total / len(self.customer_reviews)

        if self.average_rating >= 4.5 and len(self.customer_reviews) >= 10:
            self.trigger_best_seller_promotion()

    def create_review_thank_you_email(self, customer_email, rating):
        email_content = f"Dear Valued Customer,\n\n"
        email_content += f"Thank you for your {rating}-star review of {self.name}!\n"
        email_content += "Your feedback helps other customers make informed decisions.\n\n"
        if rating >= 4.0:
            email_content += "As a token of appreciation, here's a 10% discount code: REVIEW10\n\n"
        email_content += "Best regards,\nCustomer Service Team"
        return email_content

    def trigger_best_seller_promotion(self):
        promo_email = f"BESTSELLER ALERT: {self.name} is now a top-rated product with {self.average_rating} stars!"
        self.email_service.send_bulk_email(self.customer_emails, "Special Offer on Bestseller", promo_email)
        self.analytics.track_event("BESTSELLER_PROMOTION", self.product_id, {})

    def process_complex_sale(self, quantity, customer_email, shipping_address, region, card_number):
        if self.stock_quantity < quantity:
            return "FAILED: Insufficient stock"

        unit_price = self.calculate_dynamic_pricing()
        discount = self.calculate_tiered_discount(quantity)
        subtotal = unit_price * quantity * (1 - discount)
        shipping_cost = self.shipping_service.calculate_shipping_rate(region, self.weight * quantity)
        total_amount = subtotal + shipping_cost

        if not self.payment_processor.process_payment(total_amount, card_number):
            return "FAILED: Payment declined"

        self.stock_quantity -= quantity
        self.total_sales += quantity
        self.sales_by_region[region] = self.sales_by_region.get(region, 0) + quantity

        tracking_number = self.shipping_service.create_shipment(shipping_address, self.weight * quantity)

        self.database.update_stock(self.product_id, self.stock_quantity)

        receipt_email = self.generate_advanced_receipt(quantity, unit_price, discount, shipping_cost, total_amount, tracking_number)
        self.email_service.send_email(customer_email, f"Order Confirmation - {self.name}", receipt_email)

        self.check_advanced_stock_alerts()

        sale_data = {
            "quantity": str(quantity),
            "amount": str(total_amount),
            "region": region
        }
        self.analytics.track_event("SALE_COMPLETED", self.product_id, sale_data)

        self.database.log_transaction("COMPLEX_SALE", f"Product: {self.product_id}, Qty: {quantity}, Amount: ${total_amount}, Region: {region}")

        return f"SUCCESS: Order placed - Tracking: {tracking_number}"

    def generate_advanced_receipt(self, quantity, unit_price, discount, shipping, total, tracking):
        return f"""ORDER RECEIPT
Product: {self.name} ({self.product_id})
Quantity: {quantity}
Unit Price: ${unit_price:.2f}
Discount: {discount * 100:.0f}%
Shipping: ${shipping:.2f}
Total: ${total:.2f}
Tracking: {tracking}
Thank you for your order!"""

    def check_advanced_stock_alerts(self):
        if self.stock_quantity <= 5:
            urgent_alert = f"URGENT: Product {self.name} ({self.product_id}) critically low - Only {self.stock_quantity} units left!"
            self.email_service.send_email("urgent@company.com", "Critical Stock Alert", urgent_alert)
            self.analytics.track_event("CRITICAL_STOCK_ALERT", self.product_id, {})
        elif self.stock_quantity <= 20:
            alert = f"LOW STOCK: Product {self.name} has {self.stock_quantity} units remaining."
            self.email_service.send_email("inventory@company.com", "Low Stock Alert", alert)

    def execute_smart_restock(self, supplier_email):
        recommended_stock = self.calculate_optimal_stock_level()
        restock_quantity = recommended_stock - self.stock_quantity

        if restock_quantity > 0:
            self.stock_quantity += restock_quantity
            self.database.update_stock(self.product_id, self.stock_quantity)

            restock_email = self.generate_smart_restock_email(restock_quantity, recommended_stock)
            self.email_service.send_email(supplier_email, f"Smart Restock Completed - {self.name}", restock_email)

            self.analytics.track_event("SMART_RESTOCK", self.product_id, {"quantity": str(restock_quantity)})
            self.database.log_transaction("SMART_RESTOCK", f"Product: {self.product_id}, Added: {restock_quantity}, Target: {recommended_stock}")

    def calculate_optimal_stock_level(self):
        import datetime
        current_month = datetime.datetime.now().month
        average_monthly_sales = self.total_sales // max(1, current_month)
        seasonal_factor = 2 if current_month == 12 else 1
        return average_monthly_sales * 2 * seasonal_factor

    def generate_smart_restock_email(self, quantity, target_level):
        import datetime
        day_of_year = datetime.datetime.now().timetuple().tm_yday
        sales_velocity = self.total_sales / max(1, day_of_year)

        return f"""SMART RESTOCK REPORT
Product: {self.name} ({self.product_id})
Restocked Quantity: {quantity}
New Stock Level: {self.stock_quantity}
Target Level: {target_level}
Sales Velocity: {sales_velocity} units/day
Restock completed successfully."""

    def generate_comprehensive_analytics(self):
        total_revenue = self.total_sales * self.calculate_dynamic_pricing()
        profit_margin = self.calculate_complex_profit_margin()
        top_region = max(self.sales_by_region.items(), key=lambda x: x[1])[0] if self.sales_by_region else "N/A"

        return f"""COMPREHENSIVE ANALYTICS
Product: {self.name} ({self.product_id})
Total Sales: {self.total_sales} units
Revenue: ${total_revenue:.2f}
Profit Margin: {profit_margin:.2f}%
Average Rating: {self.average_rating:.2f} ({len(self.customer_reviews)} reviews)
Top Region: {top_region}
Stock Level: {self.stock_quantity}
Current Price: ${self.calculate_dynamic_pricing():.2f}"""

    def launch_marketing_campaign(self, campaign_type):
        campaign_email = self.create_campaign_email(campaign_type)
        self.email_service.send_bulk_email(self.customer_emails, f"Special Campaign - {self.name}", campaign_email)

        campaign_data = {
            "type": campaign_type,
            "reach": str(len(self.customer_emails))
        }
        self.analytics.track_event("MARKETING_CAMPAIGN", self.product_id, campaign_data)

        self.database.log_transaction("CAMPAIGN_LAUNCHED", f"Product: {self.product_id}, Type: {campaign_type}, Reach: {len(self.customer_emails)}")

    def create_campaign_email(self, campaign_type):
        if campaign_type == "SEASONAL":
            return f"Don't miss our seasonal special on {self.name}! Limited time offer with up to 25% off!"
        elif campaign_type == "CLEARANCE":
            return f"CLEARANCE ALERT: {self.name} must go! Huge discounts available now!"
        else:
            return f"Special promotion on {self.name} - Check out our latest deals!"

    def initialize_advanced_defaults(self):
        self.category = "Electronics"
        self.description = "High-quality product"
        self.supplier = "Global Supplier Inc"
        self.sales_by_region = {
            "North America": 0,
            "Europe": 0,
            "Asia": 0
        }
        # Regenerate product ID now that category is set
        self.product_id = self.generate_advanced_product_id()

    def get_name(self):
        return self.name

    def get_price(self):
        return self.price

    def set_price(self, price):
        self.price = price
        self.database.log_transaction("PRICE_UPDATE", f"Product: {self.product_id}, New price: ${price}")

    def set_discount_rate(self, rate):
        self.discount_rate = rate
        self.analytics.track_event("DISCOUNT_APPLIED", self.product_id, {"rate": str(rate)})

