public class Employee {
    private String name;
    private double baseSalary;
    private int yearsOfService;
    private String department;
    private String position;
    private String employeeId;
    private java.util.Date hireDate;
    private double performanceRating;
    private int vacationDays;
    private int usedVacationDays;
    private String manager;
    private String email;
    private String phoneNumber;
    private boolean isActive;
    private java.util.List<String> skillCertifications;
    private java.util.Map<String, String> personalInfo;
    private double overtimeHours;

    private PayrollSystem payrollSystem;
    private EmailNotificationService emailService;
    private HRDatabase hrDatabase;
    private ComplianceLogger complianceLogger;

    public Employee(String name, double baseSalary, int yearsOfService) {
        this.name = name;
        this.baseSalary = baseSalary;
        this.yearsOfService = yearsOfService;
        this.employeeId = generateUniqueEmployeeId();
        this.hireDate = new java.util.Date();
        this.vacationDays = 25;
        this.usedVacationDays = 0;
        this.performanceRating = 3.0;
        this.isActive = true;
        this.skillCertifications = new java.util.ArrayList<>();
        this.personalInfo = new java.util.HashMap<>();
        this.overtimeHours = 0.0;

        this.payrollSystem = new PayrollSystem("jdbc:mysql://localhost:3306/payroll");
        this.emailService = new EmailNotificationService("smtp.company.com");
        this.hrDatabase = new HRDatabase("jdbc:mysql://localhost:3306/hr");
        this.complianceLogger = new ComplianceLogger("/var/logs/compliance.log");

        initializeEmployeeDefaults();
    }

    public double calculateSalary() {
        return baseSalary + (yearsOfService * 1000);
    }

    public void printPaySlip() {
        System.out.println("Pay slip for " + name + ": $" + calculateSalary());
    }

    public double calculatePerformanceBonus() {
        double baseBonus = baseSalary * 0.12;
        double ratingMultiplier = performanceRating / 5.0;
        double serviceMultiplier = Math.min(yearsOfService * 0.02, 0.15);
        return baseBonus * ratingMultiplier * (1.0 + serviceMultiplier);
    }

    public double calculateOvertimeCompensation() {
        if (overtimeHours > 0) {
            double hourlyRate = baseSalary / (52 * 40);
            return overtimeHours * hourlyRate * 1.5;
        }
        return 0.0;
    }

    public double calculateTotalCompensation() {
        return calculateSalary() + calculatePerformanceBonus() + calculateOvertimeCompensation();
    }

    public double calculateFederalTax(double grossPay) {
        if (grossPay <= 4000) return grossPay * 0.18;
        else if (grossPay <= 8000) return grossPay * 0.22;
        else return grossPay * 0.28;
    }

    public double calculateStateTax(double grossPay) {
        return grossPay * 0.085;
    }

    public double calculateSocialSecurityTax(double grossPay) {
        return Math.min(grossPay * 0.062, 8853.60);
    }

    public String generateCompensationBreakdown() {
        double salary = calculateSalary();
        double bonus = calculatePerformanceBonus();
        double overtime = calculateOvertimeCompensation();
        double gross = salary + bonus + overtime;
        double federalTax = calculateFederalTax(gross);
        double stateTax = calculateStateTax(gross);
        double ssTax = calculateSocialSecurityTax(gross);
        double totalTax = federalTax + stateTax + ssTax;
        double netPay = gross - totalTax;

        StringBuilder breakdown = new StringBuilder();
        breakdown.append("=== COMPENSATION BREAKDOWN ===\n");
        breakdown.append("Base Salary: $").append(String.format("%.2f", salary)).append("\n");
        breakdown.append("Performance Bonus: $").append(String.format("%.2f", bonus)).append("\n");
        breakdown.append("Overtime Pay: $").append(String.format("%.2f", overtime)).append("\n");
        breakdown.append("Gross Pay: $").append(String.format("%.2f", gross)).append("\n");
        breakdown.append("Federal Tax: $").append(String.format("%.2f", federalTax)).append("\n");
        breakdown.append("State Tax: $").append(String.format("%.2f", stateTax)).append("\n");
        breakdown.append("Social Security: $").append(String.format("%.2f", ssTax)).append("\n");
        breakdown.append("Net Pay: $").append(String.format("%.2f", netPay)).append("\n");
        return breakdown.toString();
    }

    public void processMonthlyPayroll() {
        double grossPay = calculateTotalCompensation();
        double netPay = grossPay - (calculateFederalTax(grossPay) + calculateStateTax(grossPay) + calculateSocialSecurityTax(grossPay));

        String breakdown = generateCompensationBreakdown();
        System.out.println(breakdown);

        payrollSystem.savePayrollRecord(this, grossPay, netPay);

        String emailBody = createPayrollNotificationEmail(breakdown);
        emailService.sendEmail(email, "Monthly Payroll - " + name, emailBody);

        complianceLogger.logEvent("PAYROLL_PROCESSED", "Monthly payroll processed for employee: " + employeeId);
    }

    public String createPayrollNotificationEmail(String breakdown) {
        return "Dear " + name + ",\n\nYour monthly payroll has been processed.\n\n" + breakdown + "\n\nBest regards,\nPayroll Department";
    }

    public boolean requestVacationDays(int days) {
        if (usedVacationDays + days <= vacationDays) {
            usedVacationDays += days;

            hrDatabase.saveVacationRequest(employeeId, days, true);

            String managerEmail = createManagerNotificationEmail(days);
            emailService.sendEmail(manager + "@company.com", "Vacation Request - " + name, managerEmail);

            logVacationActivity(days, "APPROVED");
            return true;
        } else {
            logVacationActivity(days, "DENIED");
            return false;
        }
    }

    public String createManagerNotificationEmail(int days) {
        return "Manager Notification:\n\nEmployee " + name + " (" + employeeId + ") has requested " + days + " vacation days.\nRemaining balance: " + (vacationDays - usedVacationDays) + " days.\nDepartment: " + department;
    }

    public void logVacationActivity(int days, String status) {
        String logMessage = "Vacation request - Employee: " + employeeId + ", Days: " + days + ", Status: " + status;
        complianceLogger.logEvent("VACATION_REQUEST", logMessage);
    }

    public void conductAnnualPerformanceReview() {
        String reviewReport = generatePerformanceReviewReport();
        System.out.println(reviewReport);

        hrDatabase.updateEmployeeRecord(employeeId, "performance_rating", String.valueOf(performanceRating));
        hrDatabase.updateEmployeeRecord(employeeId, "last_review_date", new java.util.Date().toString());

        String reviewEmail = createPerformanceReviewEmail(reviewReport);
        emailService.sendEmail(email, "Annual Performance Review - " + name, reviewEmail);

