        self.email: Optional[str] = None

        self.hr_system = HRSystem("https://hr.company.com")
        self.notification_service = NotificationService("smtp.company.com")

    def calculate_salary(self) -> float:
        return self.base_salary + (self.years_of_service * 1000)

    def print_pay_slip(self):
        print(f"Pay slip for {self.name}: ${self.calculate_salary()}")

    def calculate_bonus(self) -> float:
        base_bonus = self.base_salary * 0.1
        if self.performance_rating >= 4.0:
            base_bonus *= 1.5
        elif self.performance_rating >= 3.5:
            base_bonus *= 1.2
        return base_bonus

    def calculate_annual_salary(self) -> float:
        return self.calculate_salary() * 12 + self.calculate_bonus()

    def process_payroll(self):
        monthly_salary = self.calculate_salary()
        taxes = self.calculate_taxes(monthly_salary)
        net_pay = monthly_salary - taxes

        print(f"Processing payroll for {self.name}")
        print(f"Gross Pay: ${monthly_salary}")
        print(f"Taxes: ${taxes}")
        print(f"Net Pay: ${net_pay}")

        self.hr_system.update_employee_record(self.employee_id, f"Payroll processed: ${net_pay}")
        self.send_payroll_email()

    def calculate_taxes(self, salary: float) -> float:
        if salary <= 3000:
            return salary * 0.15
        elif salary <= 6000:
            return salary * 0.20
        else:
            return salary * 0.25

    def request_vacation(self, days: int) -> bool:
        if self.used_vacation_days + days <= self.vacation_days:
            self.used_vacation_days += days
            print(f"Vacation request approved for {self.name}: {days} days")
            self.hr_system.update_employee_record(self.employee_id, f"Vacation approved: {days} days")
