class Book:
    def __init__(self, title, author, content):
        self._title = title
        self._author = author
        self._content = content
        self._publish_date = datetime.datetime.now()
        self._reviews = []
        self._average_rating = 0.0
        self._total_sales = 0
        self._file_storage = FileStorage("/books/storage")
        self._genre = None
        self._price = 0.0
        self._publisher = None

        self._generate_isbn()
        self._calculate_page_count()

    def print_book(self):
        print(f"Title: {self._title}")
        print(f"Author: {self._author}")
        print(f"Content: {self._content}")

    def save_to_file(self, filename):
        book_data = self._format_book_data()
        self._file_storage.save_to_file(filename, book_data)

    def _format_book_data(self):
        return f"TITLE: {self._title}\nAUTHOR: {self._author}\nISBN: {self._isbn}\nPAGES: {self._page_count}\nPRICE: ${self._price}\nRATING: {self._average_rating}\nSALES: {self._total_sales}\nCONTENT: {self._content}"

    def _generate_isbn(self):
        timestamp = int(datetime.datetime.now().timestamp() * 1000) % 10000
        random_num = random.randint(0, 999)
        self._isbn = f"978-{timestamp}-{random_num:03d}"

    def _calculate_page_count(self):
        self._page_count = max(1, len(self._content) // 250) if self._content else 1

    def validate_isbn(self, isbn):
        if not isbn or len(isbn) < 10:
            return False
        clean_isbn = re.sub(r'[^0-9X]', '', isbn)
        return len(clean_isbn) in [10, 13]

    def validate_price(self, price):
        return 0.0 <= price <= 999.99

    def add_review(self, review, rating):
        if 1.0 <= rating <= 5.0:
            self._reviews.append(review)
            if len(self._reviews) == 1:
                self._average_rating = rating
            else:
                self._average_rating = (self._average_rating * (len(self._reviews) - 1) + rating) / len(self._reviews)
            print("Review added successfully")
        else:
            print("Invalid rating. Must be between 1.0 and 5.0")

    def record_sale(self):
        self._total_sales += 1
        print(f"SALES LOG: Book sold - {self._title} (ISBN: {self._isbn}) on {datetime.datetime.now()}")
        print(f"INVENTORY: Updating stock for book: {self._isbn}")

    def calculate_royalty(self, sale_price):
        if self._total_sales > 1000:
            rate = 0.15
        elif self._total_sales > 500:
            rate = 0.12
        else:
            rate = 0.10
        return sale_price * rate

    def generate_sales_report(self):
        estimated_revenue = self._total_sales * self._price
        return f"=== SALES REPORT ===\nTitle: {self._title}\nAuthor: {self._author}\nISBN: {self._isbn}\nTotal Sales: {self._total_sales}\nAverage Rating: {self._average_rating:.2f}\nNumber of Reviews: {len(self._reviews)}\nCurrent Price: ${self._price}\nEstimated Revenue: ${estimated_revenue:.2f}"

    def print_formatted_book(self):
        formatted_output = f"====================\nBOOK INFORMATION\n====================\nTitle: {self._title}\nAuthor: {self._author}\nISBN: {self._isbn}\nGenre: {self._genre}\nPages: {self._page_count}\nPrice: ${self._price}\nPublisher: {self._publisher}\nRating: {self._average_rating}/5.0\nSales: {self._total_sales}\n====================\nCONTENT:\n{self._content}\n===================="
        print(formatted_output)

    def export_to_json(self):
        json_data = f"{{\n  \"title\": \"{self._title}\",\n  \"author\": \"{self._author}\",\n  \"isbn\": \"{self._isbn}\",\n  \"genre\": \"{self._genre}\",\n  \"pages\": {self._page_count},\n  \"price\": {self._price},\n  \"rating\": {self._average_rating},\n  \"sales\": {self._total_sales}\n}}"
        self._file_storage.save_to_file(f"{self._isbn}.json", json_data)

    # Properties
    @property
    def title(self):
        return self._title

    @title.setter
    def title(self, value):
        self._title = value

    @property
    def author(self):
        return self._author

    @author.setter
    def author(self, value):
        self._author = value

    @property
    def content(self):
        return self._content

    @content.setter
    def content(self, value):
        self._content = value
        self._calculate_page_count()

    @property
    def isbn(self):
        return self._isbn

    @property
    def genre(self):
        return self._genre

    @genre.setter
    def genre(self, value):
        self._genre = value

    @property
    def price(self):
        return self._price

    @price.setter
    def price(self, value):
        if self.validate_price(value):
            self._price = value

    @property
    def publisher(self):
        return self._publisher

    @publisher.setter
    def publisher(self, value):
        self._publisher = value

    @property
