        print(f"Product: {self.name}, Price: ${self.price}")

    def calculate_discounted_price(self, discount_percentage):
        discounted = self.price * (1 - discount_percentage / 100)
        self.database.log_transaction("DISCOUNT_APPLIED", f"Product: {self.product_id}, Discount: {discount_percentage}%")
        return discounted

    def calculate_profit_margin(self):
        return ((self.price - self.cost_price) / self.price) * 100

    def calculate_shipping_cost(self, destination):
        return 15.99 if destination.lower() == "international" else 5.99

    def add_customer_review(self, review, rating):
        if 1.0 <= rating <= 5.0:
            self.customer_reviews.append(review)
            if len(self.customer_reviews) == 1:
                self.average_rating = rating
            else:
                self.average_rating = (self.average_rating * (len(self.customer_reviews) - 1) + rating) / len(self.customer_reviews)
            self.database.log_transaction("REVIEW_ADDED", f"Product: {self.product_id}, Rating: {rating}")

    def process_sale(self, quantity, customer_email):
