class User(private var name: String, private var email: String) {
    private var password: String? = null
    private var isActive: Boolean = true
    private var role: String = "USER"
    private var lastLogin: Date? = null
    private var loginAttempts: Int = 0

    private val database = DatabaseHelper("jdbc:mysql://localhost:3306/users")
    private val emailHelper = EmailHelper("smtp.company.com")

    fun saveToDatabase() {
        val userData = "User: $name, Email: $email, Role: $role"
        database.saveUser(userData)
        println("Saving user $name to database")
    }

    fun sendWelcomeEmail() {
        emailHelper.sendEmail(email, "Welcome", "Welcome $name!")
        println("Sending welcome email to $email")
    }

    fun validateEmail(email: String): Boolean {
        if (email.isEmpty()) {
            return false
        }
        return email.contains("@") && email.contains(".")
    }

    fun validatePassword(password: String): Boolean {
        if (password.length < 8) {
            return false
        }

        val hasUpper = password.any { it.isUpperCase() }
        val hasLower = password.any { it.isLowerCase() }
        val hasDigit = password.any { it.isDigit() }

        return hasUpper && hasLower && hasDigit
    }

    fun hashPassword(password: String): String {
        var hash = 0
        for (c in password) {
            hash = hash * 31 + c.code
        }
        return kotlin.math.abs(hash).toString()
    }

    fun authenticate(password: String): Boolean {
        if (loginAttempts >= 5) {
            println("Account locked due to too many failed attempts")
            return false
        }

        if (this.password != null && this.password == hashPassword(password)) {
            loginAttempts = 0
            lastLogin = Date()
            database.updateUser(email, "Last login: $lastLogin")
            return true
        }

        loginAttempts++
        return false
    }

    fun lockAccount() {
        isActive = false
        database.updateUser(email, "Account locked")
        emailHelper.sendEmail(email, "Account Locked", "Your account has been locked")
        println("Account locked for user: $name")
    }

    fun unlockAccount() {
        isActive = true
        loginAttempts = 0
        database.updateUser(email, "Account unlocked")
        println("Account unlocked for user: $name")
    }

    // Getters and Setters
    fun getName(): String = name
    fun setName(name: String) { this.name = name }

    fun getEmail(): String = email
    fun setEmail(email: String) { this.email = email }

    fun getPassword(): String? = password
    fun setPassword(password: String) { this.password = hashPassword(password) }

    fun isActive(): Boolean = isActive

    fun getRole(): String = role
    fun setRole(role: String) { this.role = role }

    fun getLastLogin(): Date? = lastLogin

    fun getLoginAttempts(): Int = loginAttempts
}

