class Employee(private var name: String, private var baseSalary: Double, private var yearsOfService: Int) {
    private var department: String? = null
    private var position: String? = null
    private val employeeId: String = generateEmployeeId()
    private val hireDate: Date = Date()
    private var lastReviewDate: Date? = null
    private var performanceRating: Double = 3.0
    private var vacationDays: Int = 20
    private var usedVacationDays: Int = 0
    private var manager: String? = null
    private var email: String? = null

    private val hrSystem = HRSystem("https://hr.company.com")
    private val notificationService = NotificationService("smtp.company.com")

    fun calculateSalary(): Double {
        return baseSalary + (yearsOfService * 1000)
    }

    fun printPaySlip() {
        println("Pay slip for $name: $${calculateSalary()}")
    }

    fun calculateBonus(): Double {
        var baseBonus = baseSalary * 0.1
        when {
            performanceRating >= 4.0 -> baseBonus *= 1.5
            performanceRating >= 3.5 -> baseBonus *= 1.2
        }
        return baseBonus
    }

    fun calculateAnnualSalary(): Double {
        return calculateSalary() * 12 + calculateBonus()
    }

    fun processPayroll() {
        val monthlySalary = calculateSalary()
        val taxes = calculateTaxes(monthlySalary)
        val netPay = monthlySalary - taxes

        println("Processing payroll for $name")
        println("Gross Pay: $$monthlySalary")
        println("Taxes: $$taxes")
        println("Net Pay: $$netPay")

        hrSystem.updateEmployeeRecord(employeeId, "Payroll processed: $$netPay")
        sendPayrollEmail()
    }

    fun calculateTaxes(salary: Double): Double {
        return when {
            salary <= 3000 -> salary * 0.15
            salary <= 6000 -> salary * 0.20
            else -> salary * 0.25
        }
    }

    fun requestVacation(days: Int): Boolean {
        return if (usedVacationDays + days <= vacationDays) {
            usedVacationDays += days
            println("Vacation request approved for $name: $days days")
            hrSystem.updateEmployeeRecord(employeeId, "Vacation approved: $days days")
            notifyManager("Vacation request approved for $name")
            true
        } else {
            println("Vacation request denied for $name: insufficient days")
            false
        }
    }

    fun notifyManager(message: String) {
        manager?.let {
            notificationService.notifyManager(it, message)
        }
    }

    fun sendPayrollEmail() {
        email?.let {
            notificationService.sendEmail(it, "Your monthly payslip", "Please find your payslip attached.")
        }
    }

    fun conductPerformanceReview() {
        println("Conducting performance review for $name")
        println("Current rating: $performanceRating")
        lastReviewDate = Date()

        hrSystem.logPerformanceReview(employeeId, performanceRating)

        when {
            performanceRating >= 4.0 -> println("Excellent performance! Recommending for promotion.")
            performanceRating < 2.0 -> println("Performance improvement needed.")
        }
    }

    fun updatePerformanceRating(rating: Double) {
        if (rating in 1.0..5.0) {
            performanceRating = rating
            println("Performance rating updated to $rating for $name")
            hrSystem.updateEmployeeRecord(employeeId, "Performance rating: $rating")
        } else {
            println("Invalid rating. Must be between 1.0 and 5.0")
        }
    }

    private fun generateEmployeeId(): String {
        return "EMP${System.currentTimeMillis() % 10000}"
    }

    fun printEmployeeReport() {
        println("Employee Report for $name")
        println("ID: $employeeId")
        println("Department: $department")
        println("Position: $position")
        println("Hire Date: $hireDate")
        println("Years of Service: $yearsOfService")
        println("Base Salary: $$baseSalary")
        println("Performance Rating: $performanceRating")
        println("Vacation Days Remaining: ${vacationDays - usedVacationDays}")
    }

    // Getters and Setters
    fun getName(): String = name
    fun setName(name: String) { this.name = name }

    fun getBaseSalary(): Double = baseSalary
    fun setBaseSalary(baseSalary: Double) { this.baseSalary = baseSalary }

    fun getYearsOfService(): Int = yearsOfService
    fun setYearsOfService(yearsOfService: Int) { this.yearsOfService = yearsOfService }

    fun getDepartment(): String? = department
    fun setDepartment(department: String?) { this.department = department }

    fun getPosition(): String? = position
    fun setPosition(position: String?) { this.position = position }

    fun getEmployeeId(): String = employeeId

    fun getHireDate(): Date = hireDate

    fun getPerformanceRating(): Double = performanceRating

    fun getVacationDays(): Int = vacationDays
    fun setVacationDays(vacationDays: Int) { this.vacationDays = vacationDays }

    fun getManager(): String? = manager
    fun setManager(manager: String?) { this.manager = manager }

    fun getEmail(): String? = email
    fun setEmail(email: String?) { this.email = email }

    fun getUsedVacationDays(): Int = usedVacationDays
}

