class Book(private var title: String, private var author: String, private var content: String) {
    private var isbn: String = ""
    private val publishDate: Date = Date()
    private var genre: String? = null
    private var pageCount: Int = 0
    private var price: Double = 0.0
    private var publisher: String? = null
    private val reviews: MutableList<String> = mutableListOf()
    private var averageRating: Double = 0.0
    private var totalSales: Int = 0

    private val fileStorage = FileStorage("/books/storage")

    init {
        generateISBN()
        calculatePageCount()
    }

    fun printBook() {
        println("Title: $title")
        println("Author: $author")
        println("Content: $content")
    }

    fun saveToFile(filename: String) {
        val bookData = formatBookData()
        fileStorage.saveToFile(filename, bookData)
    }

    private fun formatBookData(): String {
        return "TITLE: $title\nAUTHOR: $author\nISBN: $isbn\nPAGES: $pageCount\nPRICE: $$price\nRATING: $averageRating\nSALES: $totalSales\nCONTENT: $content"
    }

    private fun generateISBN() {
        val timestamp = System.currentTimeMillis() % 10000
        val randomNum = Random.nextInt(1000)
        isbn = "978-$timestamp-${String.format("%03d", randomNum)}"
    }

    private fun calculatePageCount() {
        pageCount = if (content.isNotEmpty()) maxOf(1, content.length / 250) else 1
    }

    fun validateISBN(isbn: String): Boolean {
        if (isbn.length < 10) return false
        val cleanISBN = isbn.replace(Regex("[^0-9X]"), "")
        return cleanISBN.length == 10 || cleanISBN.length == 13
    }

    fun validatePrice(price: Double): Boolean {
        return price >= 0.0 && price <= 999.99
    }

    fun addReview(review: String, rating: Double) {
        if (rating in 1.0..5.0) {
            reviews.add(review)
            averageRating = if (reviews.size == 1) {
                rating
            } else {
                (averageRating * (reviews.size - 1) + rating) / reviews.size
            }
            println("Review added successfully")
        } else {
            println("Invalid rating. Must be between 1.0 and 5.0")
        }
    }

    fun recordSale() {
        totalSales++
        println("SALES LOG: Book sold - $title (ISBN: $isbn) on ${Date()}")
        println("INVENTORY: Updating stock for book: $isbn")
    }

    fun calculateRoyalty(salePrice: Double): Double {
        val rate = when {
            totalSales > 1000 -> 0.15
            totalSales > 500 -> 0.12
            else -> 0.10
        }
        return salePrice * rate
    }

    fun generateSalesReport(): String {
        return "=== SALES REPORT ===\nTitle: $title\nAuthor: $author\nISBN: $isbn\nTotal Sales: $totalSales\nAverage Rating: ${String.format("%.2f", averageRating)}\nNumber of Reviews: ${reviews.size}\nCurrent Price: $$price\nEstimated Revenue: ${String.format("%.2f", totalSales * price)}"
    }

    fun printFormattedBook() {
        val formattedOutput = "====================\nBOOK INFORMATION\n====================\nTitle: $title\nAuthor: $author\nISBN: $isbn\nGenre: $genre\nPages: $pageCount\nPrice: $$price\nPublisher: $publisher\nRating: $averageRating/5.0\nSales: $totalSales\n====================\nCONTENT:\n$content\n===================="
        println(formattedOutput)
    }

    fun exportToJSON() {
        val json = """
            {
              "title": "$title",
              "author": "$author",
              "isbn": "$isbn",
              "genre": "$genre",
              "pages": $pageCount,
              "price": $price,
              "rating": $averageRating,
              "sales": $totalSales
            }
        """.trimIndent()
        fileStorage.saveToFile("$isbn.json", json)
    }

    // Getters and Setters
    fun getTitle(): String = title
    fun setTitle(title: String) { this.title = title }

    fun getAuthor(): String = author
    fun setAuthor(author: String) { this.author = author }

    fun getContent(): String = content
    fun setContent(content: String) {
        this.content = content
        calculatePageCount()
    }

    fun getIsbn(): String = isbn

    fun getPublishDate(): Date = publishDate

    fun getGenre(): String? = genre
    fun setGenre(genre: String?) { this.genre = genre }

    fun getPageCount(): Int = pageCount

    fun getPrice(): Double = price
    fun setPrice(price: Double) {
        if (validatePrice(price)) {
            this.price = price
        }
    }

    fun getPublisher(): String? = publisher
    fun setPublisher(publisher: String?) { this.publisher = publisher }

    fun getReviews(): List<String> = reviews.toList()

    fun getAverageRating(): Double = averageRating

    fun getTotalSales(): Int = totalSales
}

