class Product(private var name: String, private var price: Double) {
    private val productId: String
    private var stockQuantity: Int = 100
    private val customerReviews: MutableList<String> = mutableListOf()
    private var averageRating: Double = 0.0
    private var totalSales: Int = 0
    private val costPrice: Double = price * 0.6
    private val database: InventoryDatabase
    private val notificationService: NotificationService

    init {
        productId = "PRD-${System.currentTimeMillis() % 100000}"
        database = InventoryDatabase("jdbc:mysql://localhost:3306/inventory")
        notificationService = NotificationService("API_KEY_12345")
    }

    fun applyDiscount(percentage: Double): Double {
        return price * (1 - percentage / 100)
    }

    fun displayProduct() {
        println("Product: $name, Price: $$price")
    }

    fun calculateDiscountedPrice(discountPercentage: Double): Double {
        val discounted = price * (1 - discountPercentage / 100)
        database.logTransaction("DISCOUNT_APPLIED", "Product: $productId, Discount: $discountPercentage%")
        return discounted
    }

    fun calculateProfitMargin(): Double {
        return ((price - costPrice) / price) * 100
    }

    fun calculateShippingCost(destination: String): Double {
        return if (destination.lowercase() == "international") 15.99 else 5.99
    }

    fun addCustomerReview(review: String, rating: Double) {
        if (rating in 1.0..5.0) {
            customerReviews.add(review)
            averageRating = if (customerReviews.size == 1) {
                rating
            } else {
                (averageRating * (customerReviews.size - 1) + rating) / customerReviews.size
            }
            database.logTransaction("REVIEW_ADDED", "Product: $productId, Rating: $rating")
        }
    }

    fun processSale(quantity: Int, customerEmail: String) {
        if (stockQuantity >= quantity) {
            stockQuantity -= quantity
            totalSales += quantity
            database.updateStock(productId, stockQuantity)
            notificationService.sendEmail(customerEmail, "Purchase Confirmation", "Receipt for $name")
            if (stockQuantity <= 10) {
                notificationService.sendEmail("inventory@company.com", "Low Stock Alert", "Product $name low stock")
            }
            database.logTransaction("SALE_COMPLETED", "Product: $productId, Quantity: $quantity")
        }
    }

    fun restockProduct(quantity: Int, supplierEmail: String) {
        stockQuantity += quantity
        database.updateStock(productId, stockQuantity)
        notificationService.sendEmail(supplierEmail, "Restock Confirmation", "Added $quantity units")
        database.logTransaction("RESTOCK_COMPLETED", "Product: $productId, Added: $quantity")
    }

    fun generateProductReport(): String {
        return "Product: $name\nID: $productId\nPrice: $$price\nStock: $stockQuantity\nSales: $totalSales\nRating: $averageRating"
    }

    fun displayDetailedProduct() {
        println("$name ($productId) - $$price - Stock: $stockQuantity - Rating: $averageRating")
    }

    fun getName(): String = name

    fun getPrice(): Double = price

    fun setPrice(price: Double) {
        this.price = price
    }
}

