object SecurityConfig {
    const val MAX_LOGIN_ATTEMPTS = 5
    const val PASSWORD_EXPIRY_DAYS = 90
}

class User(var name: String, var email: String) {
    var password: String? = null
    var isActive: Boolean = true
    var role: String = "USER"
    var lastLogin: Date? = null
    var loginAttempts: Int = 0
    var phoneNumber: String? = null
    var registrationDate: Date = Date()
    var loginHistory: MutableList<String> = mutableListOf()
    var preferences: MutableMap<String, String> = mutableMapOf()
    var notifications: MutableList<String> = mutableListOf()
    var profilePictureUrl: String? = null
    var emailVerified: Boolean = false

    private val dbService = DatabaseService("jdbc:mysql://localhost:3306/userdb")
    private val emailService = EmailService("smtp.company.com", 587)
    private val smsService = SMSService("api_key_12345")
    private val fileService = FileService("/uploads")

    init {
        initializeDefaultPreferences()
    }

    fun saveToDatabase() {
        dbService.saveUser(this)
    }

    fun sendWelcomeEmail() {
        val subject = "Welcome to our platform!"
        val body = createWelcomeEmailBody()
        emailService.sendEmail(email, subject, body)
    }

    fun sendPasswordResetEmail() {
        val resetToken = generatePasswordResetToken()
        val subject = "Password Reset Request"
        val body = createPasswordResetEmailBody(resetToken)
        emailService.sendEmail(email, subject, body)
    }

    fun sendSMSVerification() {
        phoneNumber?.let {
            val smsCode = generateSMSVerificationCode()
            val message = "Your verification code: $smsCode"
            smsService.sendSMS(it, message)
        }
    }

    fun createWelcomeEmailBody(): String {
        return "Dear $name,\n\nWelcome to our platform! Complete your profile and explore our features.\n\nBest regards,\nThe Team"
    }

    fun createPasswordResetEmailBody(token: String): String {
        return "Hello $name,\n\nReset your password: https://oursite.com/reset?token=$token\n\nLink expires in 24 hours."
    }

    fun generatePasswordResetToken(): String {
        val timestamp = System.currentTimeMillis()
        val randomPart = Random.nextDouble().toString().substring(2, 8)
        return "RESET_${timestamp}_$randomPart"
    }

    fun generateSMSVerificationCode(): String {
        return Random.nextInt(100000, 1000000).toString()
    }

    fun validateEmailFormat(email: String): Boolean {
        if (email.isBlank()) return false
        return email.contains("@") && email.contains(".") && email.split("@").size == 2
    }

    fun validatePasswordStrength(password: String): Boolean {
        if (password.length < 8) return false

        val hasUpper = password.any { it.isUpperCase() }
        val hasLower = password.any { it.isLowerCase() }
        val hasDigit = password.any { it.isDigit() }
        val hasSpecial = password.any { "!@#$%^&*()_+-=[]{}|;:,.<>?".contains(it) }

        return hasUpper && hasLower && hasDigit && hasSpecial
    }

    fun hashPassword(password: String): String {
        var hash = 7
        for (char in password) {
            hash = hash * 31 + char.code
        }
        return "HASH:${kotlin.math.abs(hash).toString(16).uppercase()}"
    }

    fun verifyPassword(plainPassword: String, hashedPassword: String): Boolean {
        val computedHash = hashPassword(plainPassword)
        return computedHash == hashedPassword
    }

    fun authenticate(password: String): Boolean {
        if (loginAttempts >= SecurityConfig.MAX_LOGIN_ATTEMPTS) {
            println("Account locked due to too many failed attempts")
            return false
        }

        if (this.password != null && verifyPassword(password, this.password!!)) {
            loginAttempts = 0
            lastLogin = Date()
            addToLoginHistory("Successful login from IP: 192.168.1.100")
            return true
        }

        loginAttempts++
        addToLoginHistory("Failed login attempt from IP: 192.168.1.100")
        return false
    }

    fun lockAccount() {
        isActive = false
        logSecurityEvent("ACCOUNT_LOCKED", "Account locked for user: $name")
        sendAccountNotification("Your account has been locked due to security reasons.")
    }

    fun unlockAccount() {
        isActive = true
        loginAttempts = 0
        logSecurityEvent("ACCOUNT_UNLOCKED", "Account unlocked for user: $name")
        sendAccountNotification("Your account has been successfully unlocked.")
    }

    fun logSecurityEvent(eventType: String, description: String) {
        val timestamp = Date()
        val logEntry = "[$timestamp] $eventType: $description"
        println("SECURITY LOG: $logEntry")
    }

    fun sendAccountNotification(message: String) {
        addNotification(message)
        if (emailVerified) {
            emailService.sendEmail(email, "Account Security Alert", message)
        }
        phoneNumber?.let {
            smsService.sendSMS(it, "Security Alert: $message")
        }
    }

    fun addToLoginHistory(entry: String) {
        val timestampedEntry = "${Date()}: $entry"
        loginHistory.add(timestampedEntry)
        if (loginHistory.size > 100) {
            loginHistory.removeAt(0)
        }
    }

    private fun initializeDefaultPreferences() {
        preferences["theme"] = "light"
        preferences["language"] = "en"
        preferences["notifications"] = "enabled"
    }

    fun updatePreference(key: String, value: String) {
        val oldValue = preferences[key]
        preferences[key] = value
        logPreferenceChange(key, oldValue, value)
    }

    fun logPreferenceChange(key: String, oldValue: String?, newValue: String) {
        val logEntry = "Preference '$key' changed from '$oldValue' to '$newValue'"
        println("PREFERENCE LOG: $logEntry")
    }

    fun getPreference(key: String): String? {
        return preferences[key]
    }

    fun uploadProfilePicture(imageData: ByteArray, fileName: String) {
        if (validateImageFile(imageData, fileName)) {
            profilePictureUrl = fileService.uploadFile(imageData, "profile_${name}_$fileName")
            logActivityEvent("PROFILE_PICTURE_UPLOADED", "User uploaded new profile picture")
        } else {
            throw IllegalArgumentException("Invalid image file")
        }
    }

    fun validateImageFile(imageData: ByteArray, fileName: String): Boolean {
        if (imageData.isEmpty() || imageData.size > 5 * 1024 * 1024) {
            return false
        }
        val lower = fileName.lowercase()
        return lower.endsWith(".jpg") || lower.endsWith(".jpeg") || 
               lower.endsWith(".png") || lower.endsWith(".gif")
    }

    fun logActivityEvent(eventType: String, description: String) {
        val timestamp = Date()
        val logEntry = "[$timestamp] $eventType: $description (User: $name)"
        println("ACTIVITY LOG: $logEntry")
    }

    fun addNotification(message: String) {
        val timestampedNotification = "${Date()}: $message"
        notifications.add(timestampedNotification)
        if (notifications.size > 50) {
            notifications.removeAt(0)
        }
    }

    fun changePassword(oldPassword: String, newPassword: String) {
        if (!authenticate(oldPassword)) {
            throw SecurityException("Current password is incorrect")
        }

        if (!validatePasswordStrength(newPassword)) {
            throw IllegalArgumentException("New password does not meet strength requirements")
        }

        password = hashPassword(newPassword)
        logSecurityEvent("PASSWORD_CHANGED", "Password changed successfully")
        sendAccountNotification("Your password has been changed successfully.")
    }

    fun generateUserReport(): String {
        return buildString {
            appendLine("=== USER REPORT ===")
            appendLine("Name: $name")
            appendLine("Email: $email")
            appendLine("Active: $isActive")
            appendLine("Registration Date: $registrationDate")
            appendLine("Login History: ${loginHistory.size} entries")
        }
    }

    fun deleteAccount() {
        logSecurityEvent("ACCOUNT_DELETION_STARTED", "User initiated account deletion")
        isActive = false
        email = "[DELETED]"
        password = null
        loginHistory.clear()
        notifications.clear()
        dbService.deleteUser(name)
        logSecurityEvent("ACCOUNT_DELETED", "Account deletion completed")
    }

    fun setPassword(password: String) {
        this.password = hashPassword(password)
    }
}

