class Employee(
    var name: String,
    var baseSalary: Double,
    var yearsOfService: Int
) {
    var department: String? = null
    var position: String? = null
    val employeeId: String = generateUniqueEmployeeId()
    val hireDate: Date = Date()
    var performanceRating: Double = 3.0
    var vacationDays: Int = 25
    var usedVacationDays: Int = 0
    var manager: String? = null
    var email: String? = null
    var phoneNumber: String? = null
    var isActive: Boolean = true
    val skillCertifications: MutableList<String> = mutableListOf()
    val personalInfo: MutableMap<String, String> = mutableMapOf()
    var overtimeHours: Double = 0.0

    private val payrollSystem = PayrollSystem("jdbc:mysql://localhost:3306/payroll")
    private val emailService = EmailNotificationService("smtp.company.com")
    private val hrDatabase = HRDatabase("jdbc:mysql://localhost:3306/hr")
    private val complianceLogger = ComplianceLogger("/var/logs/compliance.log")

    init {
        initializeEmployeeDefaults()
    }

    fun calculateSalary(): Double {
        return baseSalary + (yearsOfService * 1000)
    }

    fun printPaySlip() {
        println("Pay slip for $name: $${calculateSalary()}")
    }

    fun calculatePerformanceBonus(): Double {
        val baseBonus = baseSalary * 0.12
        val ratingMultiplier = performanceRating / 5.0
        val serviceMultiplier = min(yearsOfService * 0.02, 0.15)
        return baseBonus * ratingMultiplier * (1.0 + serviceMultiplier)
    }

    fun calculateOvertimeCompensation(): Double {
        return if (overtimeHours > 0) {
            val hourlyRate = baseSalary / (52 * 40)
            overtimeHours * hourlyRate * 1.5
        } else {
            0.0
        }
    }

    fun calculateTotalCompensation(): Double {
        return calculateSalary() + calculatePerformanceBonus() + calculateOvertimeCompensation()
    }

    fun calculateFederalTax(grossPay: Double): Double {
        return when {
            grossPay <= 4000 -> grossPay * 0.18
            grossPay <= 8000 -> grossPay * 0.22
            else -> grossPay * 0.28
        }
    }

    fun calculateStateTax(grossPay: Double): Double {
        return grossPay * 0.085
    }

    fun calculateSocialSecurityTax(grossPay: Double): Double {
        return min(grossPay * 0.062, 8853.60)
    }

    fun generateCompensationBreakdown(): String {
        val salary = calculateSalary()
        val bonus = calculatePerformanceBonus()
        val overtime = calculateOvertimeCompensation()
        val gross = salary + bonus + overtime
        val federalTax = calculateFederalTax(gross)
        val stateTax = calculateStateTax(gross)
        val ssTax = calculateSocialSecurityTax(gross)
        val totalTax = federalTax + stateTax + ssTax
        val netPay = gross - totalTax

        return buildString {
            appendLine("=== COMPENSATION BREAKDOWN ===")
            appendLine("Base Salary: $${String.format("%.2f", salary)}")
            appendLine("Performance Bonus: $${String.format("%.2f", bonus)}")
            appendLine("Overtime Pay: $${String.format("%.2f", overtime)}")
            appendLine("Gross Pay: $${String.format("%.2f", gross)}")
            appendLine("Federal Tax: $${String.format("%.2f", federalTax)}")
            appendLine("State Tax: $${String.format("%.2f", stateTax)}")
            appendLine("Social Security: $${String.format("%.2f", ssTax)}")
            append("Net Pay: $${String.format("%.2f", netPay)}")
        }
    }

    fun processMonthlyPayroll() {
        val grossPay = calculateTotalCompensation()
        val netPay = grossPay - (calculateFederalTax(grossPay) + calculateStateTax(grossPay) + calculateSocialSecurityTax(grossPay))

        val breakdown = generateCompensationBreakdown()
        println(breakdown)

        payrollSystem.savePayrollRecord(this, grossPay, netPay)

        val emailBody = createPayrollNotificationEmail(breakdown)
        emailService.sendEmail(email ?: "", "Monthly Payroll - $name", emailBody)

        complianceLogger.logEvent("PAYROLL_PROCESSED", "Monthly payroll processed for employee: $employeeId")
    }

    fun createPayrollNotificationEmail(breakdown: String): String {
        return "Dear $name,\n\nYour monthly payroll has been processed.\n\n$breakdown\n\nBest regards,\nPayroll Department"
    }

    fun requestVacationDays(days: Int): Boolean {
        return if (usedVacationDays + days <= vacationDays) {
            usedVacationDays += days

            hrDatabase.saveVacationRequest(employeeId, days, true)

            val managerEmail = createManagerNotificationEmail(days)
            emailService.sendEmail("${manager}@company.com", "Vacation Request - $name", managerEmail)

            logVacationActivity(days, "APPROVED")
            true
        } else {
            logVacationActivity(days, "DENIED")
            false
        }
    }

    fun createManagerNotificationEmail(days: Int): String {
        return "Manager Notification:\n\nEmployee $name ($employeeId) has requested $days vacation days.\nRemaining balance: ${vacationDays - usedVacationDays} days.\nDepartment: $department"
    }

    fun logVacationActivity(days: Int, status: String) {
        val logMessage = "Vacation request - Employee: $employeeId, Days: $days, Status: $status"
        complianceLogger.logEvent("VACATION_REQUEST", logMessage)
    }

    fun conductAnnualPerformanceReview() {
        val reviewReport = generatePerformanceReviewReport()
        println(reviewReport)

        hrDatabase.updateEmployeeRecord(employeeId, "performance_rating", performanceRating.toString())
        hrDatabase.updateEmployeeRecord(employeeId, "last_review_date", Date().toString())

        val reviewEmail = createPerformanceReviewEmail(reviewReport)
        emailService.sendEmail(email ?: "", "Annual Performance Review - $name", reviewEmail)

        complianceLogger.logEvent("PERFORMANCE_REVIEW", "Annual review completed for employee: $employeeId")
    }

    fun generatePerformanceReviewReport(): String {
        return buildString {
            appendLine("=== ANNUAL PERFORMANCE REVIEW ===")
            appendLine("Employee: $name ($employeeId)")
            appendLine("Department: $department")
            appendLine("Current Rating: $performanceRating/5.0")
            appendLine("Years of Service: $yearsOfService")
            appendLine("Certifications: ${skillCertifications.size}")

            when {
                performanceRating >= 4.5 -> appendLine("Recommendation: Promotion candidate")
                performanceRating < 2.5 -> appendLine("Recommendation: Performance improvement plan required")
            }
        }.trimEnd()
    }

    fun createPerformanceReviewEmail(report: String): String {
        return "Dear $name,\n\nYour annual performance review has been completed.\n\n$report\n\nPlease schedule a meeting to discuss.\n\nHR Department"
    }

    fun updateRatingWithNotifications(newRating: Double) {
        val oldRating = this.performanceRating
        this.performanceRating = newRating

        hrDatabase.updateEmployeeRecord(employeeId, "performance_rating", newRating.toString())

        if (kotlin.math.abs(newRating - oldRating) >= 1.0) {
            val alertEmail = createRatingChangeAlert(oldRating, newRating)
            emailService.sendEmail("hr@company.com", "Significant Rating Change - $name", alertEmail)
        }

        logPerformanceChange(oldRating, newRating)
    }

    fun createRatingChangeAlert(oldRating: Double, newRating: Double): String {
        val changeType = if (newRating > oldRating) "IMPROVEMENT" else "DECLINE"
        return "PERFORMANCE ALERT:\n\nEmployee: $name ($employeeId)\nOld Rating: $oldRating\nNew Rating: $newRating\nChange: $changeType"
    }

    fun logPerformanceChange(oldRating: Double, newRating: Double) {
        val change = "Performance rating changed - Employee: $employeeId, From: $oldRating, To: $newRating"
        complianceLogger.logEvent("RATING_CHANGE", change)
    }

