class Book(var title: String, val author: String, var content: String) {
    var isbn: String = ""
    val publishDate: Date = Date()
    var genre: String = ""
    var pageCount: Int = 0
    var price: Double = 0.0
    var publisher: String = ""
    val reviews: MutableList<String> = mutableListOf()
    var averageRating: Double = 0.0
    var totalSales: Int = 0
    val customerEmails: MutableList<String> = mutableListOf()
    var isAvailable: Boolean = true
    var format: String = "paperback"
    var discountRate: Double = 0.0

    private val fileStorage = FileStorage("/books/storage")
    private val emailService = EmailService("smtp.bookstore.com")
    private val dbService = DatabaseService("jdbc:mysql://localhost:3306/bookstore")
    private val printer = PrinterService("BookStore_Printer_001")

    init {
        initializeBookDefaults()
    }

    fun printBook() {
        println("Title: $title\nAuthor: $author\nContent: $content")
    }

    fun saveToFile(filename: String) {
        val bookData = formatCompleteBookData()
        fileStorage.saveToFile(filename, bookData)
        dbService.saveBook(this)
    }

    fun formatCompleteBookData(): String {
        return "TITLE: $title\nAUTHOR: $author\nISBN: $isbn\nGENRE: $genre\nPAGES: $pageCount\nPRICE: $${calculateFinalPrice()}\nFORMAT: $format\nPUBLISHER: $publisher\nRATING: $averageRating\nSALES: $totalSales\nAVAILABLE: $isAvailable\nCONTENT: $content"
    }

    fun generateUniqueISBN() {
        val timestamp = System.currentTimeMillis()
        val category = if (genre == "fiction") "FIC" else "NF"
        isbn = "978-$category-${timestamp % 100000}-${String.format("%02d", Random.nextInt(100))}"
    }

    fun calculateDynamicPageCount() {
        if (content.isNotEmpty()) {
            val basePages = content.length / 250
            val formatMultiplier = if (format == "hardcover") 1.2 else 1.0
            pageCount = max(1, (basePages * formatMultiplier).toInt())
        }
    }

    fun validateCompleteBookData(): Boolean {
        return title.isNotBlank() && 
               author.isNotBlank() && 
               validateISBNFormat(isbn) && 
               validatePriceRange(price) && 
               content.isNotEmpty()
    }

    fun validateISBNFormat(isbn: String): Boolean {
        if (isbn.isEmpty()) return false
        val clean = isbn.replace("[^0-9X]".toRegex(), "")
        return clean.length == 10 || clean.length == 13
    }

    fun validatePriceRange(price: Double): Boolean {
        return price in 0.99..999.99
    }

    fun processCustomerReview(customerEmail: String, review: String, rating: Double) {
        if (rating in 1.0..5.0) {
            reviews.add(review)
            customerEmails.add(customerEmail)
            recalculateRatingMetrics(rating)
            sendReviewConfirmationEmail(customerEmail)
            logReviewActivity(customerEmail, rating)
        }
    }

    fun recalculateRatingMetrics(newRating: Double) {
        averageRating = if (reviews.size == 1) {
            newRating
        } else {
            (averageRating * (reviews.size - 1) + newRating) / reviews.size
        }
    }

    fun sendReviewConfirmationEmail(customerEmail: String) {
        val subject = "Thank you for reviewing: $title"
        val body = createReviewThankYouEmail()
        emailService.sendEmail(customerEmail, subject, body)
    }

    fun createReviewThankYouEmail(): String {
        return "Dear Reader,\n\nThank you for reviewing '$title' by $author.\nYour feedback helps other readers discover great books!\n\nBest regards,\nBookstore Team"
    }

    fun logReviewActivity(customerEmail: String, rating: Double) {
        val logDetails = "Review added - Book: $isbn, Customer: $customerEmail, Rating: $rating"
        dbService.logTransaction("REVIEW_ADDED", logDetails)
    }

    fun processSaleTransaction(customerEmail: String) {
        totalSales++
        customerEmails.add(customerEmail)

        updateInventoryStatus()

        dbService.updateSalesData(isbn, totalSales)

        val receiptEmail = generateSalesReceiptEmail()
        emailService.sendEmail(customerEmail, "Purchase Confirmation - $title", receiptEmail)

        logSalesTransaction(customerEmail)

        if (totalSales % 100 == 0) {
            sendMilestoneNotification()
        }
    }

    fun updateInventoryStatus() {
        if (totalSales > 1000) {
            isAvailable = Random.nextDouble() > 0.1
        }
    }

    fun generateSalesReceiptEmail(): String {
        val finalPrice = calculateFinalPrice()
        return "PURCHASE RECEIPT\n\nTitle: $title\nAuthor: $author\nISBN: $isbn\nFormat: $format\nOriginal Price: $$price\nDiscount: ${discountRate * 100}%\nFinal Price: $${String.format("%.2f", finalPrice)}\nThank you for your purchase!"
    }

    fun logSalesTransaction(customerEmail: String) {
        val logDetails = "Sale completed - Book: $isbn, Customer: $customerEmail, Price: $${calculateFinalPrice()}"
        dbService.logTransaction("SALE_COMPLETED", logDetails)
    }

    fun sendMilestoneNotification() {
        val subject = "Sales Milestone Reached: $title"
        val body = "Congratulations! '$title' has reached $totalSales sales!"
        emailService.sendEmail("sales@bookstore.com", subject, body)
    }

    fun calculateFinalPrice(): Double {
        return price * (1.0 - discountRate)
    }

    fun calculateAuthorRoyalty(): Double {
        val baseRate = when {
            totalSales > 5000 -> 0.18
            totalSales > 1000 -> 0.15
            else -> 0.10
        }
        return totalSales * calculateFinalPrice() * baseRate
    }

    fun generateComprehensiveReport(): String {
        val revenue = totalSales * calculateFinalPrice()
        val royalty = calculateAuthorRoyalty()
        return "=== COMPREHENSIVE BOOK REPORT ===\nTitle: $title\nAuthor: $author\nISBN: $isbn\nGenre: $genre\nFormat: $format\nTotal Sales: $totalSales\nRevenue: $${String.format("%.2f", revenue)}\nAuthor Royalty: $${String.format("%.2f", royalty)}\nAverage Rating: ${String.format("%.2f", averageRating)}\nReviews: ${reviews.size}\nAvailable: $isAvailable"
    }

    fun printDetailedReport() {
        val report = generateComprehensiveReport()
        println(report)
        printer.printReport(report)
    }

    fun sendMarketingCampaign() {
        if (customerEmails.isNotEmpty()) {
            val campaignEmail = createMarketingEmail()
            emailService.sendBulkEmail(customerEmails, "New Release from $author", campaignEmail)
            logMarketingActivity()
        }
    }

    fun createMarketingEmail(): String {
        return "Dear Valued Reader,\n\nSince you enjoyed '$title', you might like our new releases from $author.\nCheck out our latest collection with special discounts!\n\nHappy Reading!"
    }

    fun logMarketingActivity() {
        dbService.logTransaction("MARKETING_SENT", "Campaign sent for book: $isbn to ${customerEmails.size} customers")
    }

    fun exportToMultipleFormats() {
        val jsonData = "{\"title\":\"$title\",\"author\":\"$author\",\"isbn\":\"$isbn\",\"sales\":$totalSales,\"rating\":$averageRating}"
        fileStorage.saveToFile("$isbn.json", jsonData)

        val xmlData = "<book><title>$title</title><author>$author</author><isbn>$isbn</isbn><sales>$totalSales</sales></book>"
        fileStorage.saveToFile("$isbn.xml", xmlData)
    }

    fun initializeBookDefaults() {
        generateUniqueISBN()
        calculateDynamicPageCount()
        genre = "general"
        price = 19.99
        publisher = "Independent Press"
    }

    fun applyDiscount(discountPercentage: Double) {
        if (discountPercentage in 0.0..0.5) {
            discountRate = discountPercentage
            notifyCustomersOfDiscount()
        }
    }

    fun notifyCustomersOfDiscount() {
        if (customerEmails.isNotEmpty()) {
            val discountEmail = "Special Offer: ${discountRate * 100}% off on '$title'! Limited time only."
            emailService.sendBulkEmail(customerEmails, "Special Discount - $title", discountEmail)
        }
    }

    fun setContent(newContent: String) {
        content = newContent
        calculateDynamicPageCount()
    }

    fun setPrice(newPrice: Double) {
        if (validatePriceRange(newPrice)) {
            price = newPrice
        }
    }

    fun setFormat(newFormat: String) {
        format = newFormat
        calculateDynamicPageCount()
    }
}

