public class User
{
    private string name;
    private string email;
    private string password;
    private bool isActive;
    private string role;
    private DateTime? lastLogin;
    private int loginAttempts;

    private DatabaseHelper database;
    private EmailHelper emailHelper;

    public User(string name, string email)
    {
        this.name = name;
        this.email = email;
        this.isActive = true;
        this.role = "USER";
        this.loginAttempts = 0;
        this.database = new DatabaseHelper("Server=localhost;Database=users;Integrated Security=true;");
        this.emailHelper = new EmailHelper("smtp.company.com");
    }

    public void SaveToDatabase()
    {
        string userData = $"User: {name}, Email: {email}, Role: {role}";
        database.SaveUser(userData);
        Console.WriteLine($"Saving user {name} to database");
    }

    public void SendWelcomeEmail()
    {
        emailHelper.SendEmail(email, "Welcome", $"Welcome {name}!");
        Console.WriteLine($"Sending welcome email to {email}");
    }

    public bool ValidateEmail(string email)
    {
        if (string.IsNullOrEmpty(email))
        {
            return false;
        }
        return email.Contains("@") && email.Contains(".");
    }

    public bool ValidatePassword(string password)
    {
        if (string.IsNullOrEmpty(password) || password.Length < 8)
        {
            return false;
        }

        bool hasUpper = password.Any(char.IsUpper);
        bool hasLower = password.Any(char.IsLower);
        bool hasDigit = password.Any(char.IsDigit);

        return hasUpper && hasLower && hasDigit;
    }

    public string HashPassword(string password)
    {
        int hash = 0;
        foreach (char c in password)
        {
            hash = hash * 31 + c;
        }
        return Math.Abs(hash).ToString();
    }

    public bool Authenticate(string password)
    {
        if (loginAttempts >= 5)
        {
            Console.WriteLine("Account locked due to too many failed attempts");
            return false;
        }

        if (this.password != null && this.password == HashPassword(password))
        {
            loginAttempts = 0;
            lastLogin = DateTime.Now;
            database.UpdateUser(email, $"Last login: {lastLogin}");
            return true;
        }

        loginAttempts++;
        return false;
    }

    public void LockAccount()
    {
        isActive = false;
        database.UpdateUser(email, "Account locked");
        emailHelper.SendEmail(email, "Account Locked", "Your account has been locked");
        Console.WriteLine($"Account locked for user: {name}");
    }

    public void UnlockAccount()
    {
        isActive = true;
        loginAttempts = 0;
        database.UpdateUser(email, "Account unlocked");
        Console.WriteLine($"Account unlocked for user: {name}");
    }

    // Properties
    public string Name
    {
        get { return name; }
        set { name = value; }
    }

    public string Email
    {
        get { return email; }
        set { email = value; }
    }

    public string Password
    {
        get { return password; }
        set { password = HashPassword(value); }
    }

    public bool IsActive
    {
        get { return isActive; }
    }

    public string Role
    {
        get { return role; }
        set { role = value; }
    }

    public DateTime? LastLogin
    {
        get { return lastLogin; }
    }

    public int LoginAttempts
    {
        get { return loginAttempts; }
    }
}

