        this.publishDate = DateTime.Now;
        this.reviews = new List<string>();
        this.averageRating = 0.0;
        this.totalSales = 0;
        this.fileStorage = new FileStorage("/books/storage");

        GenerateISBN();
        CalculatePageCount();
