    private string FormatBookData()
    {
        return $"TITLE: {title}\nAUTHOR: {author}\nISBN: {isbn}\nPAGES: {pageCount}\nPRICE: ${price}\nRATING: {averageRating}\nSALES: {totalSales}\nCONTENT: {content}";
    }

    private void GenerateISBN()
    {
        long timestamp = DateTimeOffset.Now.ToUnixTimeMilliseconds() % 10000;
        int randomNum = new Random().Next(1000);
        isbn = $"978-{timestamp}-{randomNum:D3}";
    }

    private void CalculatePageCount()
    {
        pageCount = !string.IsNullOrEmpty(content) ? Math.Max(1, content.Length / 250) : 1;
    }

    public bool ValidateISBN(string isbn)
    {
        if (string.IsNullOrEmpty(isbn) || isbn.Length < 10) return false;
        string cleanISBN = Regex.Replace(isbn, @"[^0-9X]", "");
        return cleanISBN.Length == 10 || cleanISBN.Length == 13;
    }

    public bool ValidatePrice(double price)
    {
        return price >= 0.0 && price <= 999.99;
    }

    public void AddReview(string review, double rating)
    {
        if (rating >= 1.0 && rating <= 5.0)
        {
            reviews.Add(review);
            averageRating = reviews.Count == 1 ? rating : (averageRating * (reviews.Count - 1) + rating) / reviews.Count;
            Console.WriteLine("Review added successfully");
        }
        else
        {
            Console.WriteLine("Invalid rating. Must be between 1.0 and 5.0");
        }
    }

    public void RecordSale()
    {
        totalSales++;
        Console.WriteLine($"SALES LOG: Book sold - {title} (ISBN: {isbn}) on {DateTime.Now}");
        Console.WriteLine($"INVENTORY: Updating stock for book: {isbn}");
    }

    public double CalculateRoyalty(double salePrice)
    {
        double rate = totalSales > 1000 ? 0.15 : (totalSales > 500 ? 0.12 : 0.10);
        return salePrice * rate;
    }

    public string GenerateSalesReport()
    {
        double estimatedRevenue = totalSales * price;
        return $"=== SALES REPORT ===\nTitle: {title}\nAuthor: {author}\nISBN: {isbn}\nTotal Sales: {totalSales}\nAverage Rating: {averageRating:F2}\nNumber of Reviews: {reviews.Count}\nCurrent Price: ${price}\nEstimated Revenue: ${estimatedRevenue:F2}";
    }

    public void PrintFormattedBook()
    {
        string formattedOutput = $"====================\nBOOK INFORMATION\n====================\nTitle: {title}\nAuthor: {author}\nISBN: {isbn}\nGenre: {genre}\nPages: {pageCount}\nPrice: ${price}\nPublisher: {publisher}\nRating: {averageRating}/5.0\nSales: {totalSales}\n====================\nCONTENT:\n{content}\n====================";
        Console.WriteLine(formattedOutput);
    }

    public void ExportToJSON()
    {
        string json = $@"{{
  ""title"": ""{title}"",
  ""author"": ""{author}"",
  ""isbn"": ""{isbn}"",
  ""genre"": ""{genre}"",
  ""pages"": {pageCount},
  ""price"": {price},
  ""rating"": {averageRating},
  ""sales"": {totalSales}
}}";
        fileStorage.SaveToFile($"{isbn}.json", json);
    }

    // Properties
    public string Title
    {
        get => title;
        set => title = value;
    }

    public string Author
    {
        get => author;
        set => author = value;
    }

    public string Content
    {
        get => content;
        set
        {
            content = value;
            CalculatePageCount();
        }
    }

